// Makes plain `ssh prod`, `scp` and `git` work for saved SSH credentials. The
// Vault owns one generated file, and ~/.ssh/config gets one Include line for it.
// Everything else in that file stays as it was.
import * as fs from 'node:fs/promises';
import path from 'node:path';
import { randomUUID } from 'node:crypto';

const quoted = value => `"${String(value).replace(/["\\]/g, '\\$&')}"`;
// ssh expands %d and friends in these, so a literal % has to be doubled.
const literal = value => String(value).replace(/%/g, '%%');

export function sshConfigText(credentials, { root }) {
  const blocks = credentials.filter(row => row.type === 'ssh').sort((a, b) => a.id.localeCompare(b.id, 'en')).map(row => {
    const { host, port, username, auth } = row.fields;
    const touch = path.join(root, 'usage', row.id + '.touch');
    const lines = [`Host ${row.id}`, `  HostName ${host}`, `  Port ${port}`, `  User ${username}`,
      `  UserKnownHostsFile ${quoted(literal(path.join(root, 'known_hosts', row.id)))}`, '  GlobalKnownHostsFile /dev/null', `  HostKeyAlias ${row.id}`, '  StrictHostKeyChecking yes',
      '  PermitLocalCommand yes', `  LocalCommand /usr/bin/touch ${quoted(literal(touch))} 2>/dev/null`];
    if (auth === 'key') lines.push(`  IdentityFile ${quoted(literal(path.join(root, 'keys', row.id)))}`, '  IdentitiesOnly yes', '  PreferredAuthentications publickey', '  BatchMode yes');
    else lines.push('  PubkeyAuthentication no', '  PreferredAuthentications password,keyboard-interactive');
    return lines.join('\n');
  });
  return '# Generated by t3-vault. Changes here are replaced. Manage these in Setup → Vault.\n\n' + blocks.join('\n\n') + (blocks.length ? '\n' : '');
}

const includeLine = file => `Include ${quoted(file)}`;

/** True if ~/.ssh/config already reads the generated file. */
export async function hasInclude({ home, file, effects = fs }) {
  try { return (await effects.readFile(path.join(home, '.ssh/config'), 'utf8')).split(/\r?\n/).some(line => line.trim() === includeLine(file)); }
  catch { return false; }
}

/**
 * Adds the Include at the top, where ssh reads it before any `Host *` block.
 * Returns false rather than guess if ~/.ssh/config is a link or isn't ours to
 * write, and `t3-vault ssh` keeps working either way.
 */
export async function ensureInclude({ home, file, effects = fs }) {
  const directory = path.join(home, '.ssh'), target = path.join(directory, 'config');
  try {
    await effects.mkdir(directory, { recursive: true, mode: 0o700 });
    let existing = '', mode = 0o600;
    try {
      const stat = await effects.lstat(target);
      if (!stat.isFile()) return false;
      existing = await effects.readFile(target, 'utf8'); mode = stat.mode & 0o777;
    } catch (error) { if (error.code !== 'ENOENT') return false; }
    if (existing.split(/\r?\n/).some(line => line.trim() === includeLine(file))) return true;
    const temporary = path.join(directory, '.' + randomUUID() + '.tmp');
    try {
      const handle = await effects.open(temporary, 'wx', mode);
      try { await handle.writeFile(includeLine(file) + '\n\n' + existing); await handle.sync(); } finally { await handle.close(); }
      await effects.rename(temporary, target);
    } finally { await effects.rm(temporary, { force: true }); }
    return true;
  } catch { return false; }
}
